const fs=require('node:fs'),assert=require('node:assert/strict');
const {H,L,seed,next,step,finishRound,canonical,OUT,sha}=require('./simulate-walkthrough-p2-20261101.cjs');
const started=performance.now(),s0=seed();L.normalize(s0);const initial=H.load(H.save(s0)),proof=H.load(H.save(s0));let cycleSeconds=0;const cycleRounds=[];
for(let i=0;i<5;i++){const before=proof.legacy.points,seconds=finishRound(proof);cycleSeconds+=seconds;cycleRounds.push({axiom:proof.legacy.axiom,seconds,earned:String(BigInt(proof.legacy.points)-BigInt(before)),freshCanonicalHash:sha(canonical(proof))});}
assert(canonical(initial)===canonical(proof),'normalized persistent state must repeat after five native rounds');assert(cycleRounds.every(r=>r.seconds<60&&r.earned==='601'));assert.equal(L.legacyMultiplier(proof),4000);
const cyclePoints=BigInt(proof.legacy.points)-BigInt(initial.legacy.points),best=proof.legacy.bestSeconds;
function skip(s,count){if(!count)return;assert(s.legacy.rebuilding&&s.legacy.rebuild===0);const dt=count*cycleSeconds;s.time+=dt;s.legacy.roundStart=s.time;s.legacy.round=String(BigInt(s.legacy.round)+BigInt(count)*5n);s.legacy.points=String(BigInt(s.legacy.points)+BigInt(count)*cyclePoints);s.legacy.bestSeconds=Math.min(s.legacy.bestSeconds||Infinity,best);s.log=proof.log.map(r=>({t:s.time,m:r.m.replace(/^第 \d+ 次归一/,'第 '+s.legacy.round+' 次归一')}));}
function advance(s,seconds){const blocks=Math.max(0,Math.floor(seconds/cycleSeconds));skip(s,blocks);let left=seconds-blocks*cycleSeconds,nativeSteps=0;while(left>1e-7){const dt=Math.min(left,next(s));step(s,dt);left=Math.max(0,left-dt);nativeSteps++;}return {blocks,skippedRounds:blocks*5,nativeSteps,roundingRemainder:left};}
function save(s,label,seconds,work){const file='checkpoint-'+label+'.ht5',raw=H.exportStr(s),restored=H.importStr(raw);assert.equal(restored.legacy.round,s.legacy.round);assert.equal(restored.legacy.points,s.legacy.points);fs.writeFileSync(OUT+'/'+file,raw);return {label,seconds,file,sha256:sha(raw),round:s.legacy.round,roundsAdded:String(BigInt(s.legacy.round)-225000n),points:s.legacy.points,pointsAdded:String(BigInt(s.legacy.points)-66000000n),era:s.era,axiom:s.legacy.axiom,multiplier:L.legacyMultiplier(s),currentRoundSeconds:s.time-s.legacy.roundStart,bestSeconds:s.legacy.bestSeconds,stars:Object.values(s.archive).reduce((n,a)=>n+a.stars.reduce((x,y)=>x+y,0),0),blueprints:s.blueprints.length,legalNativeImport:true,...work};}
const horizons=[['1day',86400],['1week',604800],['1month',2592000],['1year',31536000],['10years',315360000],['100years',3153600000]],rows=[];
for(const [label,seconds]of horizons){const s=H.load(H.save(initial)),work=advance(s,seconds);rows.push(save(s,label,seconds,work));}
const farReplays=[];
for(const count of [0,1000,100000,Math.floor(3153600000/cycleSeconds)]){
 const before=H.load(H.save(initial));skip(before,count);const expected=H.load(H.save(before));skip(expected,1);const actual=H.load(H.save(before));let seconds=0;for(let i=0;i<5;i++)seconds+=finishRound(actual);
 const coreEqual=canonical(expected)===canonical(actual),counterEqual=expected.legacy.round===actual.legacy.round&&expected.legacy.points===actual.legacy.points,clockError=Math.abs(actual.time-expected.time),bestError=Math.abs(actual.legacy.bestSeconds-expected.legacy.bestSeconds);
 assert(coreEqual&&counterEqual);assert(clockError<.01&&bestError<.01);H.importStr(H.exportStr(actual));
 farReplays.push({offsetCycles:count,offsetSeconds:count*cycleSeconds,additionalNativeRounds:5,coreEqual,counterEqual,clockAbsoluteErrorSeconds:clockError,bestAbsoluteErrorSeconds:bestError,legalNativeImport:true,blueprintIdsEqual:JSON.stringify(expected.blueprints.map(x=>x.id))===JSON.stringify(actual.blueprints.map(x=>x.id)),archiveEqual:JSON.stringify(expected.archive)===JSON.stringify(actual.archive),workshopEqual:JSON.stringify(expected.workshop)===JSON.stringify(actual.workshop),canonicalHash:sha(canonical(actual))});
}
const result={kind:'exact repeated-state cycle batching, not fitted forecasting',baseline:{historicalProfile:true,description:'用户历史明确提出的225000次归一、6600万太一；隔离重建为XX已完成、720星、10张手动代表、携带MA+natural+fixed，无挑战/工坊规则。初态本轮年龄600秒，先正常执行归一，获得61太一，再开始计未来时间。仅模拟未来推进，不声称模拟了之前22.5万轮或实际解题耗时。',round:'225000',points:'66000000',stars:720,blueprints:10,carry:['MA','natural','fixed'],initialAction:{normalize:true,earned:'61'},initialRawSha256:sha(H.exportStr(s0))},units:{day:86400,week:604800,monthDays:30,yearDays:365},cycle:{rounds:5,seconds:cycleSeconds,points:String(cyclePoints),rows:cycleRounds,fullPersistentCoreRecurs:true,canonicalExcludedDomains:['time','last (wall-clock timestamp)','log (current normalization message)','legacy.round','legacy.points','legacy.roundStart','legacy.bestSeconds'],proof:['遗产倍率只依赖点数、元公理和携带项；6600万起已达到4000硬上限，未来点数单增不会离开此上限。','归一用H.newState重建；只保留blueprints/archive/workshop/ach/ui/time/legacy累积字段。工坊禁用且无规则，蓝图档案不再修改，没有新ID。','各轮不同只由round%5元公理影响；五轮后全部持久核心逐字段一致，source中的其它round使用均为显示或未启用的传感器。','五轮均小于60秒，结算使用max(60,轮秒)，故每轮严格floor(36000/60)+1=601；floor无需拟合或近似。','批处理只跳过完整5轮，更新轮数、整数遗产、绝对时钟、当前归一日志与bestSeconds；不足5轮的末段由同一原生H.tick事件积分。','远距离原生重放核验完整非累积持久状态、整数计数、archive、蓝图ID和规则时钟。浮点绝对时间和best显示域保留显式误差记录；不把IEEE浮点加法重排说成逐bit相等。'],sourceFiles:['src/era11.js','src/late-eras.js','src/systems.js'].map(file=>({file,sha256:sha(fs.readFileSync('D:/hypertower-recovery-20261026/hypertower/'+file))}))},rows,farReplays,wallSeconds:(performance.now()-started)/1000};fs.writeFileSync(OUT+'/long-horizons.json',JSON.stringify(result,null,2));console.log(JSON.stringify({cycle:result.cycle.seconds,rows:rows.map(r=>({label:r.label,round:r.round,points:r.points,era:r.era})),farReplays,wallSeconds:result.wallSeconds},null,2));
